/**
 * Uploaded files in the msc-web-media bucket. Keys are generated by the server and match MEDIA_KEY_PATTERN, so
 * nothing here ever builds a key from request input.
 * msc-web-media 存储桶中的上传文件。键由服务器生成并符合 MEDIA_KEY_PATTERN，因此这里从不使用请求输入拼接键。
 */

export async function putMediaObject(bucket: R2Bucket, key: string, bytes: ArrayBuffer | Uint8Array, contentType: string, fileName: string): Promise<void> {
  await bucket.put(key, bytes, {
    httpMetadata: { contentType },
    customMetadata: { fileName },
  });
}

export function getMediaObject(bucket: R2Bucket, key: string, options?: R2GetOptions): Promise<R2ObjectBody | R2Object | null> {
  return bucket.get(key, options);
}

/** R2 deletes at most this many keys per call. */
/** R2 每次调用最多删除这么多个键。 */
const KEYS_PER_DELETE = 1000;

export async function deleteMediaObjects(bucket: R2Bucket, keys: readonly string[]): Promise<void> {
  for (let start = 0; start < keys.length; start += KEYS_PER_DELETE) await bucket.delete(keys.slice(start, start + KEYS_PER_DELETE));
}
